import React from 'react';

/* Geometric background pattern matching Rectangle_9.png */
const BgPattern = () => (
  <svg
    viewBox="0 0 900 640"
    xmlns="http://www.w3.org/2000/svg"
    preserveAspectRatio="xMidYMid slice"
    style={{ width: '100%', height: '100%' }}
  >
    <defs>
      <style>{`.r{fill:none;stroke:#c8c8c8;}`}</style>
    </defs>
    {/* top-left circle */}
    {[140,120,100,80,62,46,32,19].map((r,i)=>(
      <circle key={i} cx="180" cy="120" r={r} className="r" strokeWidth={i<2?8:i<4?6:i<6?5:4}/>
    ))}
    {/* top-right rounded rect */}
    {[300,262,224,188,154,120,86,52].map((s,i)=>(
      <rect key={i} cx={650-(300-s)/2} cy={-20+(300-s)/2}
        x={550+(300-s)/2} y={-30+(300-s)/2}
        width={s} height={s} rx={s*0.38} className="r"
        strokeWidth={i<2?8:i<4?6:5}/>
    ))}
    {/* center large rounded rect */}
    {[340,302,264,228,192,158,124,90,56].map((s,i)=>(
      <rect key={i}
        x={270+(340-s)/2} y={190+(340-s)/2}
        width={s} height={s} rx={s*0.38} className="r"
        strokeWidth={i<2?9:i<4?7:i<6?6:i<8?5:4}/>
    ))}
    {/* left side circle */}
    {[190,168,146,124,102,82,62,44,28].map((r,i)=>(
      <circle key={i} cx="60" cy="410" r={r} className="r" strokeWidth={i<2?9:i<4?7:i<6?5:4}/>
    ))}
    {/* right circle */}
    {[200,178,156,134,112,90,70,50,32].map((r,i)=>(
      <circle key={i} cx="830" cy="380" r={r} className="r" strokeWidth={i<2?9:i<4?7:i<6?5:4}/>
    ))}
    {/* bottom center circle */}
    {[170,150,130,110,90,72,54].map((r,i)=>(
      <circle key={i} cx="490" cy="595" r={r} className="r" strokeWidth={i<2?8:i<4?6:5}/>
    ))}
  </svg>
);

const Hero = () => {
  const s = {
    section: {
      paddingTop: 66,
      background: '#F4F4F4',
      position: 'relative',
      overflow: 'hidden',
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      fontFamily: 'Poppins, sans-serif',
    },
    bgWrap: {
      position: 'absolute',
      inset: 0,
      zIndex: 0,
      opacity: 0.7,
    },
    wrapper: {
      maxWidth: 1200, margin: '0 auto', padding: '80px 32px 0',
      position: 'relative', zIndex: 1, flex: 1,
      display: 'flex', flexDirection: 'column', justifyContent: 'center',
    },
    h1: {
      fontFamily: 'Poppins, sans-serif',
      fontSize: 52, fontWeight: 800,
      lineHeight: 1.12, color: '#111',
      maxWidth: 700, marginBottom: 32,
      letterSpacing: '-2px',
    },
    h1Orange: { color: '#FF5A00' },
    sub: {
      fontSize: 14.5, color: '#777',
      maxWidth: 500, lineHeight: 1.8,
      fontFamily: 'Poppins, sans-serif', fontWeight: 400,
      marginBottom: 40,
    },
    btn: {
      display: 'inline-flex', alignItems: 'center',
      background: 'transparent',
      color: '#FF5A00',
      padding: '13px 26px',
      borderRadius: 10,
      fontSize: 14, fontWeight: 600,
      border: '1.8px solid #FF5A00',
      cursor: 'pointer',
      fontFamily: 'Poppins, sans-serif',
      transition: 'all .2s',
      marginBottom: 60,
    },
    partnersWrap: {
      display: 'flex', alignItems: 'center', gap: 8,
      flexWrap: 'wrap', marginBottom: 60,
    },
    partnerLabel: { fontSize: 12, color: '#999', fontFamily: 'Poppins, sans-serif' },
    chip: {
      background: '#EBEBEB', color: '#555',
      padding: '5px 14px', borderRadius: 20,
      fontSize: 11.5, fontWeight: 600,
      fontFamily: 'Poppins, sans-serif',
    },
  };

  const partners = ['BBDA', 'Orange Burkina', 'BSL', 'MTDPCE', 'SITHO', 'SIAO'];

  return (
    <section style={s.section}>
      <div style={s.bgWrap}><BgPattern /></div>

      <div style={s.wrapper}>
        <h1 style={s.h1}>
          <span style={s.h1Orange}>Une plateforme</span> qui vous connecte à<br />
          tout ce qui fait vivre l'événementiel.
        </h1>

        <p style={s.sub}>
          Contrary to popular belief, Lorem Ipsum is not simply random text. It has roots in a
          piece of classical Latin literature from{' '}
          45 BC, making it over 2000 years old. Richard McClintock, a Latin professor at
          Hampden-Sydney College in Virginia, .
        </p>

        <button style={s.btn}>Voir les évènements</button>

        <div style={s.partnersWrap}>
          <span style={s.partnerLabel}>Reconnu par :</span>
          {partners.map(p => (
            <span key={p} style={s.chip}>{p}</span>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Hero;
